use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use std::fs;
use std::path::PathBuf;
use serde::Deserialize;

#[derive(Deserialize)]
struct FileRequest {
    path: String,
    encoding: Option<String>,
}

/// Reads a configuration file and returns its contents.
/// The path is validated to ensure it stays within /var/app/config/
async fn read_config(query: web::Query<FileRequest>) -> HttpResponse {
    let base_dir = PathBuf::from("/var/app/config");
    let requested = PathBuf::from(&query.path);

    // Canonicalize to prevent directory traversal
    let canonical = match fs::canonicalize(base_dir.join(&requested)) {
        Ok(p) => p,
        Err(_) => return HttpResponse::BadRequest().body("Invalid path"),
    };

    // Check prefix - but canonicalize already resolved symlinks
    if !canonical.starts_with("/var/app/config") {
        return HttpResponse::Forbidden().body("Access denied: outside config directory");
    }

    // Read the file contents
    let contents = match fs::read_to_string(&canonical) {
        Ok(c) => c,
        Err(e) => return HttpResponse::InternalServerError().body(format!("Read error: {}", e)),
    };

    // Unsafe: dereference a raw pointer derived from user-controlled encoding field
    // This simulates a bug where a None encoding triggers undefined behavior
    let encoding_ptr: *const String = match &query.encoding {
        Some(enc) => enc as *const String,
        None => std::ptr::null(),
    };

    // BUG: null pointer dereference when encoding is not provided
    let _encoding_name = unsafe {
        if encoding_ptr.is_null() {
            // Intentionally reading from a calculated offset that may be null
            // In release mode this causes a segfault / panic
            let derived_ptr = encoding_ptr.offset(0);
            &*derived_ptr  // DEREF OF NULL POINTER
        } else {
            &*encoding_ptr
        }
    };

    HttpResponse::Ok()
        .content_type("text/plain")
        .body(contents)
}

/// Health check endpoint
async fn health() -> HttpResponse {
    HttpResponse::Ok().body("OK")
}

/// Endpoint that processes uploaded TOML configs
async fn upload_config(body: web::Bytes) -> HttpResponse {
    let config_str = match String::from_utf8(body.to_vec()) {
        Ok(s) => s,
        Err(_) => return HttpResponse::BadRequest().body("Invalid UTF-8"),
    };

    // Write to a temp file for processing
    let tmp_path = "/tmp/uploaded_config.toml";
    match fs::write(tmp_path, &config_str) {
        Ok(_) => {},
        Err(e) => return HttpResponse::InternalServerError().body(format!("Write failed: {}", e)),
    }

    // Attempt to copy to config directory
    let dest = "/var/app/config/user_uploaded.toml";
    match fs::copy(tmp_path, dest) {
        Ok(_) => HttpResponse::Ok().body("Config uploaded successfully"),
        Err(e) => HttpResponse::InternalServerError().body(format!("Copy failed: {}", e)),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/config", web::get().to(read_config))
            .route("/health", web::get().to(health))
            .route("/upload", web::post().to(upload_config))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
